// @ts-check
// Single flat ESLint config for the whole monorepo (ESLint 9+/10).
// Packages run `eslint .` from their own directory; this config is found by
// traversing upwards, so every package lints under the same rules.
import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";

export default tseslint.config(
  {
    ignores: [
      "**/node_modules/**",
      "**/dist/**",
      "**/.next/**",
      "**/coverage/**",
      "**/drizzle/**",
      "**/*.d.ts",
      "packages/runner/sft-dev.mjs",
      // Generated by `pnpm --filter @sft/parser build:graph` (esbuild bundle).
      "packages/parser/bin/build-graph.js",
    ],
  },
  js.configs.recommended,
  {
    // Plain JS (tooling scripts + the pinned runner).
    files: ["**/*.js", "**/*.mjs", "**/*.cjs"],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: "module",
      globals: { ...globals.node },
    },
    rules: {
      "no-unused-vars": ["error", { argsIgnorePattern: "^_", caughtErrors: "none" }],
    },
  },
  ...tseslint.configs.recommended,
  {
    files: ["**/*.ts", "**/*.tsx"],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: "module",
    },
    rules: {
      // TypeScript already checks identifiers; core no-undef is redundant and
      // wrong for TS-specific globals.
      "no-undef": "off",
      "@typescript-eslint/no-explicit-any": "error",
      "@typescript-eslint/no-unused-vars": [
        "error",
        { argsIgnorePattern: "^_", varsIgnorePattern: "^_", caughtErrors: "none" },
      ],
      "@typescript-eslint/consistent-type-imports": ["error", { prefer: "type-imports" }],
    },
  },
  {
    // NestJS resolves constructor dependencies through `design:paramtypes`, so
    // every class used as an injection token MUST be a value import: a
    // type-only import erases the class reference and DI fails at boot
    // ("Nest can't resolve dependencies of the X (?, Object)"). This override
    // applies to the API only; the worker, schemas and parser packages have no
    // DI framework and keep the rule.
    files: ["apps/api/src/**/*.ts"],
    rules: {
      "@typescript-eslint/consistent-type-imports": "off",
    },
  },
);
